namespace WypozyczalniaSportowa.Domain; public sealed class RentalLine { private decimal _price; public RentalLine(Equipment equipment, decimal price) { Equipment = equipment; ChargedPrice = price; } public Equipment Equipment { get; } public decimal ChargedPrice { get => _price; private set => _price = value < 0 ? throw new Exceptions.DomainValidationException("Kwota pozycji nie może być ujemna.") : value; } public RentalLine Clone(bool deep) => new(deep ? Equipment.CloneEntity(true) : Equipment, ChargedPrice); public override string ToString() => $"{Equipment.Name}: {ChargedPrice:C}"; }
